def the_death_and_the_burial(case, data):
    """F3 — Deut 34:5-6 — ONE LINE moses_died_and_was_buried (ACT) writing moses_died_by_the_mouth_of_the_lord and buried_by_the_lord_grave_unknown (STATUSES on Moses) and three_gifts_merits_withdrawn_at_the_third_death (a STATUS on Israel), REUSING gathered_to_his_people at 34:5 on Moses (Aaron's word — THE SONG'S OWED POINTER 32:50 -> 34:5 PAID, the POINTER ROW 34:5); THE DEATH IN AARON'S WORDS (chukat, journeys by CALL — RUN CITATIONS), the three gifts (beha, chukat, covenant_return_charge by CALL — Taanit 9a), who wrote 'and Moses died there' a DISPUTE row; THE GRAVE IN GAD'S PORTION (blessing_of_moses, gad_reuben by CALL — THE BLESSING'S OWED POINTER PAID, the POINTER ROW 34:6; Tosefta Sotah 4:4, Sotah 1:7 and 1:9 the cases), the burial by the LORD Himself (second_tablets, joseph, family by CALL)"""
    del P_[:]
    ask = case['ask']
    if ask == 'moses_the_servant_of_the_lord_died_there_in_the_land_of_moab_by_the_mouth_of_the_lord':
        ink('34:5', "'AND MOSES THE SERVANT OF THE LORD DIED THERE IN THE LAND OF MOAB BY THE MOUTH OF THE LORD' — THE DEATH IN AARON'S WORDS: 'by the mouth of the LORD' Numbers 33:38's (the twin %d; eighteen seats in the Torah), 'and he died' Numbers 20:28's (the twin %d), and 32:50's sentence ('die in the mountain … as Aaron your brother died') SHARES NO TOKEN (the twin %d — the twin by sense alone); 'the servant of the LORD' once in the Torah, nineteen in the Bible (Joshua 1:1's twin %d — the Prophets' first verse, cited never read); 'and Moses died there' once in the Bible; the kin computed %s (the Writings' seat, cited never read)" % (TWIN['34:5 vs Num 33:38'], TWIN['34:5 vs Num 20:28'], TWIN['34:5 vs 32:50'], TWIN['34:5 vs Josh 1:1'], KINC[(34, 5)][0]))
        move("cold_run_song_charge_nebo (CALL) — SC.the_summons_to_nebo(die_in_the_mount_where_you_go_up_and_be_gathered_to_your_people) = %s and SC.DATA moses_death_ahead = %s (32:50's command on the tape — die_in_the_mountain_gathered_to_your_people_commanded on moses: EXECUTED HERE, the owed pointer PAID); cold_run_chukat (CALL) — CK.edom_and_hor(death_dates) = %s and CK.meribah(death_by_the_kiss) = %s (Aaron's death on the tape — gathered_to_his_people REUSED, Aaron's word; the kiss Miriam's, Aaron's and Moses'); cold_run_journeys (CALL) — JR.aarons_death_retold(by_the_mouth_kiss) = %s (Numbers 33:38's 'by the mouth of the LORD' — the retelling that never writes); cold_run_beha (CALL) — BH.taberah_and_quail(three_gifts) = %s (Taanit 9a — THE THREE GIFTS BY THREE MERITS: the well returned by Moses' and Aaron's merit at Miriam's death, the cloud by Moses' at Aaron's — CK.meribah(well_by_merit) = %s; at the third death the last merit is withdrawn: the manna to the sixteenth of Nisan, Kiddushin 38a OWED); cold_run_covenant_return_charge (CALL) — CR.DATA the_three_gifts_and_their_merits = %s (the daemon owed at 34:5 — paid in the lean form as a STATUS by this chapter's daemon, the standing daemon owed to the full process)" % (SV(SC_NEBO, 50), SV(SC_DEATH, 40), SV(CK_DATES, 50), SV(CK_KISS, 40), SV(JR_MOUTH, 50), SV(BH_GIFTS, 60), SV(CK_WELL, 40), SV(CR_GIFTS, 40)), "WHO WROTE 'AND MOSES DIED THERE' — 357:28 a DISPUTE (Joshua wrote from here; Rabbi Meir: Moses wrote at dictation, in tears — Bava Batra 15a, Menachot 30a OWED): THE DATA ROW who_wrote_and_moses_died_there, no verdict of ours; the soul taken gently by the Place Himself — the trustee's parable (E26, 357:30), the angel of death refused (305:5); Onkelos 'BY THE MEMRA OF THE LORD' — the death by the Word; THE WRITES moses_died_by_the_mouth_of_the_lord (a STATUS on moses), three_gifts_merits_withdrawn_at_the_third_death (a STATUS on israel_people), THE REUSE gathered_to_his_people on moses (the sixth entry)")
        dat("THE LINE moses_died_and_was_buried (an ACT) at %s; THE WRITES moses_died_by_the_mouth_of_the_lord on moses, three_gifts_merits_withdrawn_at_the_third_death on israel_people; THE REUSE gathered_to_his_people at 34:5 on moses (REUSE_AFTER 6); THE POINTER ROW 34:5 (the song's owed pointer PAID, grade R); THE DATA ROWS the_death_in_aarons_words, who_wrote_and_moses_died_there, the_three_gifts_third_event; the readback row 34:5 SUPPLIED with its writes and REFERENCE against Aaron's death by kind (garments_transferred_and_aaron_died at Numbers 20:28)" % D1)
        return out("and Moses the servant of the LORD died there in the land of Moab by the mouth of the LORD (34:5) — the death in Aaron's words (by the mouth of the LORD Numbers 33:38's, by CALL: %s), 32:50's sentence executed without a shared token: THE SONG'S OWED POINTER PAID — gathered_to_his_people REUSED on Moses, THE POINTER ROW 34:5 grade R; THE WRITES moses_died_by_the_mouth_of_the_lord on Moses and three_gifts_merits_withdrawn_at_the_third_death on Israel (the three gifts by CALL: %s); who wrote 'and Moses died there' a dispute row" % (SV(JR_MOUTH, 40), SV(BH_GIFTS, 40)), ['moses_died_by_the_mouth_of_the_lord', 'gathered_to_his_people', 'three_gifts_merits_withdrawn_at_the_third_death'])
    if ask == 'he_buried_him_in_the_valley_in_the_land_of_moab_over_against_beth_peor':
        ink('34:6', "'AND HE BURIED HIM IN THE VALLEY IN THE LAND OF MOAB OVER AGAINST BETH-PEOR' — 'over against Beth-peor' three seats (%s — 3:29's and 4:46's; the twin %d); 34:6 with 33:21 SHARES NOTHING (the twin %d — Onkelos alone joined the lawgiver's portion to the grave); 'and He buried him' two seats (2 Kings 21:26 cited never read); Jacob's burial shares 'him' alone (the twin %d); the kin computed %s (the Prophets' seat, cited never read); the store's one blank gloss at Beth-peor written at the reading" % (P(_G('מול (over against)'), _G('בית (Beth)'), _G('פעור (Peor)'), books=None), TWIN['34:6 vs 3:29'], TWIN['34:6 vs 33:21'], TWIN['34:6 vs Gen 50:13'], KINC[(34, 6)][0]))
        move("cold_run_blessing_of_moses (CALL) — BL.DATA moses_grave_ahead = %s and BL.the_gad_lioness_and_the_lawgivers_portion(he_chose_a_first_part_for_himself_for_there_a_portion_of_a_ruler_was_reserved) = %s (Onkelos 33:21 'there in his inheritance Moses the great scribe of Israel is buried'; the Sifrei 355:6 — THE BLESSING'S OWED POINTER 33:21 -> 34:6 PAID HERE); cold_run_gad_reuben (CALL) — GR.the_cities(moses_grave) = %s (Reuben's Nebo, Gad's field — Numbers 32:38; Sotah 13b OWED); 357:31 died in Reuben's inheritance, buried in Gad's field; TOSEFTA SOTAH 4:4 THE CASE — the body borne FOUR MIL in the body of the Shekhinah (the parameter the_four_mil); cold_run_second_tablets (CALL) — ST.the_stations_and_the_death(walk_after_his_attributes) = %s (Sotah 14a's burying the dead — THE BURIAL BY THE LORD HIMSELF the callee's own row; the parameter the_burial_by_the_place); cold_run_joseph (CALL) — JO.the_oath(oath_sworn) = %s and JO.coffin(bones_closed_on_tape) = %s (MOSES MERITED JOSEPH'S BONES — MISHNAH SOTAH 1:9 THE CASE: Joseph buried his father, Moses attended Joseph's bones, the Place attended Moses' — the parameter joseph_bones_merited; MISHNAH SOTAH 1:7 measure for measure the parameter measure_for_measure); cold_run_opening_speech (CALL) — OS.the_plea(beth_peor) = %s (3:29's valley over against Beth-peor); cold_run_obey_horeb (CALL) — OH.the_exhortation(baal_peor_seen) = %s (4:3's Peor seen)" % (SV(BL_GRAVE, 40), SV(BL_PORTION, 40), SV(GR_CITY, 50), SV(ST_WALK, 50), SV(JO_OATH, 40), SV(JO_BONES, 40), SV(OS_PEOR, 40), SV(OH_PEOR, 40)), "Onkelos 'in the valley' (3:29's and 4:46's word), 'his grave' (10:6 Aaron's word); THE WRITE buried_by_the_lord_grave_unknown — a STATUS on moses (DP2); THE DATA ROW the_grave_in_gads_portion_paid; THE POINTER ROW 34:6 grade R")
        dat("THE WRITE buried_by_the_lord_grave_unknown, a STATUS on moses at %s; THE POINTER ROW 34:6 (the blessing's owed pointer PAID, grade R); THE PARAMETERS the_four_mil (Tosefta Sotah 4:4), joseph_bones_merited and the_burial_by_the_place (Sotah 1:9), measure_for_measure (Sotah 1:7); THE DATA ROW the_grave_in_gads_portion_paid; the readback row 34:6 VARIANT (Onkelos's valley; the Tosefta's four mil) with the pointer" % D1)
        return out("and He buried him in the valley in the land of Moab over against Beth-peor (34:6) — THE GRAVE IN GAD'S PORTION: Onkelos 33:21 and the Sifrei 355:6 meet 357:31 and the Tosefta's four mil (the blessing's pointer by CALL: %s; Gad's field by CALL: %s): THE BLESSING'S OWED POINTER 33:21 -> 34:6 PAID — THE POINTER ROW 34:6 grade R; the burial by the LORD Himself, Moses merited Joseph's bones (Sotah 1:9, 1:7 the cases): THE WRITE buried_by_the_lord_grave_unknown, a STATUS on Moses" % (SV(BL_GRAVE, 30), SV(GR_CITY, 30)), ['buried_by_the_lord_grave_unknown'])
    if ask == 'no_man_knows_his_grave_to_this_day':
        ink('34:6', "'AND NO MAN KNOWS HIS GRAVE TO THIS DAY' — 'no man knows' and 'his grave' once each in the Bible (the measure's list); 'to this day' the narrator's present (Joshua's 'to this day' the Prophets' idiom, cited never read); the negation the chapter's second (34:4, 34:6, 34:7 twice, 34:10 — five)")
        move("357:32 NO MAN KNOWS — not even Moses himself ('the man' Numbers 12:3 — beha by CALL: BH.miriam(as_one_dead) = %s, the humble man); the wicked kingdom's two detachments sent to find the grave — those above saw it below, those below saw it above (the parable of the hidden grave); cold_run_family (CALL) — FA.testament(buried_named) = %s (the fathers' graves NAMED — Machpelah; Moses' alone unknown); cold_run_joseph (CALL) — JO.three_deaths(buried_by_both) = %s (Isaac buried by both his sons; Moses by the LORD alone)" % (SV(BH_DEAD, 40), SV(FA_BURIED, 40), SV(JO_BOTH, 40)), "the grave unknown the status's own value (buried_by_the_lord_grave_unknown — the write of the burial's ask); NO SECOND WRITE; the Prophets' idiom 'to this day' cited never read")
        dat("no man knows his grave — the value of buried_by_the_lord_grave_unknown (the burial's write); no second write; 357:32's two detachments a DATA note inside the_grave_in_gads_portion_paid; the readback row 34:6's variant")
        return out("and no man knows his grave to this day (34:6) — not even Moses (357:32; 'the man' Numbers 12:3 by CALL: %s), the two detachments' parable; the grave unknown the burial's own status, no second write; the fathers' graves named, Moses' alone unknown" % (SV(BH_DEAD, 30),), ['accepted'])
    return 'no verdict in span', [], list(P_)

def the_years_and_the_thirty_days(case, data):
    """F4 — Deut 34:7-8 — ONE LINE moses_hundred_and_twenty_israel_wept_thirty_days (ACT) writing died_at_a_hundred_and_twenty_eye_undimmed (a STATUS on Moses) and days_of_weeping_for_moses_ended (a STATUS on Israel), REUSING mourned_thirty_days at 34:8 on Israel WITHOUT A DUE (the registry's timer row — THE THIRTY DAYS A DURATION, no timer, the counter unmoved); THE PARSER'S 120 and 30 DATA rows (covenant_return_charge by CALL — 31:2's number on the marker's day, NO SECOND MARKER; chukat by CALL — Aaron's thirty); the undimmed eye and the shining face (erection by CALL); THE NAZIRITE'S TERM from this verse (naso by CALL — Nazir 1:3 the case, I2)"""
    del P_[:]
    ask = case['ask']
    if ask == 'moses_was_a_hundred_and_twenty_years_old_when_he_died_his_eye_not_dim_nor_his_natural_force_abated':
        ink('34:7', "'AND MOSES WAS A HUNDRED AND TWENTY YEARS OLD WHEN HE DIED; HIS EYE WAS NOT DIM, NOR HIS NATURAL FORCE ABATED' — THE PARSER'S 120: the parser's hit %s (31:2's number — 'a hundred and twenty years old' these two seats alone: %s; the twin %d, four in order; the kin computed %s); Genesis 6:3's hundred and twenty (the twin %d); 'when he died' Numbers 33:39's one other seat — Aaron's (the twin %d); 'his eye was not dim' and 'nor his natural force abated' once each in the Bible; Isaac's dim eyes share nothing (the twin %d)" % (PARSE[(34, 7)][0], P(_G('בן (aged)'), _G('מאה (a hundred)'), _G('ועשרים (and twenty)'), _G('שנה (years)'), books=None), TWIN['34:7 vs 31:2'], KINC[(34, 7)][0], TWIN['34:7 vs Gen 6:3'], TWIN['34:7 vs Num 33:39'], TWIN['34:7 vs Gen 27:1'] if '34:7 vs Gen 27:1' in TWIN else 0))
        move("cold_run_covenant_return_charge (CALL) — CR.the_charge_and_the_crossing(a_hundred_and_twenty_years_old_this_day) = %s and CR.DATA the_death_date_of_moses = %s (31:2's number ON THE MARKER'S DAY — 19b's ONE MARKER, the seventh of Adar: 34:7 restates it, NO SECOND MARKER; the parser's hit a DATA row, no count in the world); cold_run_journeys (CALL) — JR.aarons_death_retold(the_date) = %s (Aaron's 'when he died' at Numbers 33:39 — a hundred and twenty-three); cold_run_exodus_story (CALL) — ES.birth(birthday) = %s (the seventh of Adar — Moses' birthday and death day, the years full); cold_run_erection (CALL) — ER.tablets(radiance) = %s (Exodus 34:29's shining face — Onkelos 'THE SPLENDOR OF THE GLORY OF HIS FACE DID NOT CHANGE': the natural force rendered the radiance, face_radiant 1 on moses); 357:33 the four who lived a hundred and twenty and the six pairs; 357:34 the eyes of the dead dim and Moses' not; 357:35 the freshness that wells even now — a 'do not read' (no code)" % (SV(CR_120, 50), SV(CR_DEATH, 40), SV(JR_DATE, 40), SV(ES_BIRTH, 20), SV(ER_RADIANCE, 40)), "THE WRITE died_at_a_hundred_and_twenty_eye_undimmed — a STATUS on moses (DP2); THE DATA ROW the_two_numbers (the parser's 120 and 30 — DATA rows, no guard needed: no count in the world)")
        dat("THE LINE moses_hundred_and_twenty_israel_wept_thirty_days (an ACT) at %s; THE WRITE died_at_a_hundred_and_twenty_eye_undimmed, a STATUS on moses; THE DATA ROW the_two_numbers — 34:7's 120 31:2's number restated on the marker's day, NO SECOND MARKER; the_death_date_of_moses 19b's calendar parameter read; the readback row 34:7 SUPPLIED with its write and REFERENCE against 31:2's marker by kind" % D1)
        return out("and Moses was a hundred and twenty years old when he died; his eye was not dim, nor his natural force abated (34:7) — 31:2's number restated on the marker's day (by CALL: %s), no second marker, the parser's 120 a DATA row; the splendor of his face unchanged (Onkelos; Exodus 34:29 by CALL): THE WRITE died_at_a_hundred_and_twenty_eye_undimmed, a STATUS on Moses" % (SV(CR_120, 40),), ['died_at_a_hundred_and_twenty_eye_undimmed'])
    if ask == 'the_children_of_israel_wept_for_moses_in_the_plains_of_moab_thirty_days':
        ink('34:8', "'AND THE CHILDREN OF ISRAEL WEPT FOR MOSES IN THE PLAINS OF MOAB THIRTY DAYS' — THE PARSER'S 30: the parser's hit %s (Aaron's thirty, Numbers 20:29 — 'thirty days' these two seats alone in the Bible: %s; the twin %d); 'and the children of Israel wept' once in the Bible; 'in the plains of Moab' eight seats — Numbers' own (26:63 the kin computed %s; 36:13 the footer among them); Egypt's weeping for Jacob shares the verb (Genesis 50:3)" % (PARSE[(34, 8)][0], P(_G('שלשים (thirty)'), _G('יום (days)'), books=None), TWIN['34:8 vs Num 20:29'], KINC[(34, 8)][0]))
        move("cold_run_chukat (CALL) — CK.edom_and_hor(thirty_days) = %s and CK.DATA aaron_mourned_by_all = %s (Aaron's thirty on the tape — aaron_mourned_thirty_days the kind, mourned_thirty_days on israel_people THE TIMER that fired at (40, 6, 1): REUSED HERE at its own forward seat WITHOUT A DUE); 357:36 'and they wept' — the men alone for Moses, the men and the women for Aaron (the peacemaker); THE THIRTY DAYS A DURATION — THE DESIGN'S RULING: a marker is the ink's own date statement (19b's 'this day' at 31:2), a duration an act's length; no timer set (the engine's _write appends an undated entry), the counter UNMOVED at (40, 12, 7); the tradition's arithmetic (Adar 7 to Nisan 7; the manna in store to the sixteenth of Nisan — Kiddushin 38a OWED; Joshua 1:11 and 4:19 the tenth of Nisan — cited never read) belongs to the next book's tape, whose first marker walks the counter" % (SV(CK_THIRTY, 50), SV(CK_MOURNED, 40)), "THE REUSE mourned_thirty_days at 34:8 on israel_people (the second entry — Aaron's Numbers 20:29 the first; the registry's op a TIMER, written without a due: no TIMER-SET); THE DATA ROW the_thirty_days_a_duration; Onkelos 'thirty days' (2:14's word, the thirty-eight years)")
        dat("THE REUSE mourned_thirty_days at 34:8 on israel_people WITHOUT A DUE (REUSE_AFTER 2 — the tape's print decides; no timer, the counter unmoved — RUN's second and third slots +0); THE DATA ROWS the_thirty_days_a_duration, the_two_numbers (34:8's 30 — Aaron's thirty); markers 173 UNMOVED; the readback row 34:8 REFERENCE against Aaron's thirty days by kind (aaron_mourned_thirty_days at Numbers 20:29) with the reuse")
        return out("and the children of Israel wept for Moses in the plains of Moab thirty days (34:8) — Aaron's thirty (Numbers 20:29, the two seats of 'thirty days'; by CALL: %s): mourned_thirty_days REUSED at its own forward seat on Israel WITHOUT A DUE — THE THIRTY DAYS A DURATION, not a marker: no timer set, the counter unmoved at Moses' last day; the next book's tape walks the counter" % (SV(CK_THIRTY, 40),), ['mourned_thirty_days'])
    if ask == 'the_days_of_weeping_in_the_mourning_for_moses_were_ended':
        ink('34:8', "'AND THE DAYS OF WEEPING IN THE MOURNING FOR MOSES WERE ENDED' — 'the days of weeping' and 'the mourning for Moses' once each in the Bible; Jacob's mourning at Atad shares the noun (Genesis 50:10); 357:36-37 THE WEEPING ONE, THE DAYS TWO, THE MOURNING THREE — the three measures of mourning read from the verse's three words; Numbers 6:4's 'all the days' the kin by the verbal analogy 'days'/'the days' (the twin %d — I2: the nazirite's term)" % (TWIN['34:8 vs Num 6:4'],))
        move("cold_run_naso (CALL) — NS.nazirite(term) = %s and NS.DATA nazir_default_days = %s (THE NAZIRITE'S TERM FROM THIS VERSE — the Sifrei 357:37 by the verbal analogy of 'days'/'the days' with Numbers 6:4 (I2, checked in MIDDOT.md): MISHNAH NAZIR 1:3 THE CASE — an unspecified naziriteship is thirty days; the parameter the_nazirites_term — naso's own DATA row read by CALL: the last chapter of the Torah supplying a datum to the sixth of Numbers, THE CODE/DATA LAW's exhibit); cold_run_family (CALL) — FA.testament(gathered) = %s (the fathers' deaths and mournings — Jacob's seventy days in Egypt, the seven at Atad)" % (SV(NS_TERM, 50), SV(NS_DAYS, 20), SV(FA_GATHERED, 40)), "THE WRITE days_of_weeping_for_moses_ended — a STATUS on israel_people (DP2) carrying the duration in its value; the thirty ended, the counter unmoved (the next book's tape walks it); Onkelos 'and the days of weeping in Moses' mourning were completed'")
        dat("THE WRITE days_of_weeping_for_moses_ended, a STATUS on israel_people at %s (the duration in its value); THE PARAMETER the_nazirites_term — MISHNAH NAZIR 1:3 THE CASE at 357:37 (I2 — Numbers 6:4 by naso's DATA nazir_default_days); the readback row 34:8's write" % D1)
        return out("and the days of weeping in the mourning for Moses were ended (34:8) — the weeping one, the days two, the mourning three (357:36-37); THE NAZIRITE'S TERM taught from this verse by the verbal analogy with Numbers 6:4 (I2; Nazir 1:3 the case — naso's default days by CALL: %s): THE WRITE days_of_weeping_for_moses_ended, a STATUS on Israel, the duration in its value" % (SV(NS_DAYS, 10),), ['days_of_weeping_for_moses_ended'])
    return 'no verdict in span', [], list(P_)
